524				RouteSecurityPolicyResolver resolver = new RouteSecurityPolicyResolver(props);
525				resolver.afterPropertiesSet();
526	
527				TraceIdGatewayFilter trace = new TraceIdGatewayFilter();
528				UntrustedHeaderStripFilter strip = new UntrustedHeaderStripFilter(new GatewaySecurityProperties());
529				RequestLogGatewayFilter logFilter = new RequestLogGatewayFilter();
530				RouteSecurityPolicyFilter security = new RouteSecurityPolicyFilter(resolver);
