532				ContextHeaderInjectionFilter inject = new ContextHeaderInjectionFilter(writer, null);
533	
534				MockServerWebExchange exchange = MockServerWebExchange.from(
535						MockServerHttpRequest.get("/public/health")
536								.header("X-Internal-Call", "1")
537								.header("X-User-Id", "attacker"));
538	
539				// Run filters in order
540				AtomicReference<ServerWebExchange> afterTrace = new AtomicReference<>();
541				trace.filter(exchange, capturingChain(afterTrace)).block();
542				ServerWebExchange e1 = afterTrace.get();
543	
544				AtomicReference<ServerWebExchange> afterStrip = new AtomicReference<>();
545				strip.filter(e1, capturingChain(afterStrip)).block();
546				ServerWebExchange e2 = afterStrip.get();
547	
548				AtomicReference<ServerWebExchange> afterLog = new AtomicReference<>();
549				logFilter.filter(e2, capturingChain(afterLog)).block();
550				ServerWebExchange e3 = afterLog.get();
551	
