748			@Test
749			@DisplayName("client-provided X-Trace-Id is captured, stripped, and re-injected downstream")
750			void clientTraceIdCapturedAndReinjected() {
751				GatewaySecurityProperties props = new GatewaySecurityProperties();
752				RouteSecurityPolicyResolver resolver = new RouteSecurityPolicyResolver(props);
753				resolver.afterPropertiesSet();
754	
755				TraceIdGatewayFilter trace = new TraceIdGatewayFilter();
756				UntrustedHeaderStripFilter strip = new UntrustedHeaderStripFilter(new GatewaySecurityProperties());
757				RouteSecurityPolicyFilter security = new RouteSecurityPolicyFilter(resolver);
758				TrustedHeaderWriter writer = new TrustedHeaderWriter();
759				ContextHeaderInjectionFilter inject = new ContextHeaderInjectionFilter(writer, null);
760	
761				MockServerWebExchange exchange = MockServerWebExchange.from(
762						MockServerHttpRequest.get("/api/data")
763								.header("X-Trace-Id", "client-supplied-trace"));
764	
765				// Step 1: capture trace ID (sanitize: reuse incoming non-blank value)
766				AtomicReference<ServerWebExchange> e1 = new AtomicReference<>();
767				trace.filter(exchange, capturingChain(e1)).block();
768	
769				// Step 2: strip (removes client X-Trace-Id from request)
770				AtomicReference<ServerWebExchange> e2 = new AtomicReference<>();
771				strip.filter(e1.get(), capturingChain(e2)).block();
772	
773				// Step 4: security policy (required before injection)
774				AtomicReference<ServerWebExchange> e4 = new AtomicReference<>();
775				security.filter(e2.get(), capturingChain(e4)).block();
776	
777				// Step 8: inject (re-writes X-Trace-Id from attribute)
778				AtomicReference<ServerWebExchange> e8 = new AtomicReference<>();
779				inject.filter(e4.get(), capturingChain(e8)).block();
780	
781				ServerWebExchange result = e8.get();
782				String downstreamTraceId = result.getRequest().getHeaders()
783						.getFirst(TraceIdGatewayFilter.TRACE_ID_HEADER);
784				String responseTraceId = result.getResponse().getHeaders()
785						.getFirst(TraceIdGatewayFilter.TRACE_ID_HEADER);
786	
787				// Client value is sanitized (reused as-is when non-blank) and re-injected
788				assertThat(downstreamTraceId).isEqualTo("client-supplied-trace");
789				// Response and downstream request carry same trace ID
790				assertThat(downstreamTraceId).isEqualTo(responseTraceId);
791			}
