692				exchange.getAttributes().put(RouteSecurityPolicyFilter.POLICY_ATTR,
693						new RouteSecurityPolicy(AuthMode.JWT, "jwt-route"));
694				AtomicReference<ServerWebExchange> captured = new AtomicReference<>();
695	
696				StepVerifier.create(customFilter.filter(exchange, capturingChain(captured)))
697						.verifyComplete();
698	
699				HttpHeaders downstreamHeaders = captured.get().getRequest().getHeaders();
700				assertThat(downstreamHeaders.getFirst("X-App-Code")).isNull();
701				assertThat(downstreamHeaders.getFirst(TIMESTAMP_HEADER)).isNull();
702				assertThat(downstreamHeaders.getFirst(SIGNATURE_HEADER)).isNull();
703			}
704		}
705	
706		// ---------- error response format ----------
707	
708		@Nested
709		@DisplayName("Error response format")
710		class ErrorResponseFormat {
711	
712			@Test
713			@DisplayName("error response is valid JSON with code and message")
714			void errorResponseIsJson() {
715				MockServerWebExchange exchange = MockServerWebExchange.from(
716						MockServerHttpRequest.post("/api/data"));
717				exchange.getAttributes().put(RouteSecurityPolicyFilter.POLICY_ATTR,
718						new RouteSecurityPolicy(AuthMode.HMAC, "hmac-route"));
719	
720				StepVerifier.create(filter().filter(exchange, passThroughChain()))
721						.verifyComplete();
722	
723				String body = exchange.getResponse().getBodyAsString().block();
724				assertThat(body).contains("\"code\"");
725				assertThat(body).contains("\"message\"");
726				assertThat(body).startsWith("{");
727				assertThat(body).endsWith("}");
728				assertThat(exchange.getResponse().getHeaders().getContentType().toString())
729						.contains("application/json");
730			}
731	
732			@Test
733			@DisplayName("error response status is 401")
734			void errorResponseIs401() {
735				MockServerWebExchange exchange = MockServerWebExchange.from(
736						MockServerHttpRequest.post("/api/data"));
737				exchange.getAttributes().put(RouteSecurityPolicyFilter.POLICY_ATTR,
738						new RouteSecurityPolicy(AuthMode.HMAC, "hmac-route"));
739	
740				StepVerifier.create(filter().filter(exchange, passThroughChain()))
741						.verifyComplete();
742	
743				assertThat(exchange.getResponse().getStatusCode().value()).isEqualTo(401);
744			}
745		}
